namespace Ordering;

/// <summary>Imports orders from a batch of delimited rows.</summary>
public sealed class OrderImporter
{
    private readonly OrderRepository _repository;

    public OrderImporter(OrderRepository repository) => _repository = repository;

    public IReadOnlyList<Order> ImportBatch(IEnumerable<string> rows)
    {
        var imported = new List<Order>();
        var seen = new HashSet<string>(StringComparer.Ordinal);

        foreach (var row in rows)
        {
            if (!TryParseOrder(row, out var order))
                continue;
            if (!seen.Add(order.Reference))
                continue;

            _repository.Add(order);
            imported.Add(order);
        }

        return imported;
    }

    private static bool TryParseOrder(string row, out Order order)
    {
        order = null!;
        if (string.IsNullOrWhiteSpace(row)) return false;

        var parts = row.Split(',');
        if (parts.Length < 4 || !TryCreateOrder(parts[0], parts[1], out order))
            return false;

        AddValidLines(order, parts);
        return order.Lines.Count > 0;
    }

    private static bool TryCreateOrder(string recordType, string reference, out Order order)
    {
        order = null!;
        var type = recordType.Trim();
        var refTrimmed = reference.Trim();
        if (refTrimmed.Length == 0) return false;

        switch (type)
        {
            case "H":
            case "ORDER":
                order = new Order { Reference = refTrimmed, Channel = OrderChannel.Web };
                return true;
            case "M":
                order = new Order { Reference = refTrimmed, Channel = OrderChannel.Marketplace };
                return true;
            default:
                return false;
        }
    }

    private static void AddValidLines(Order order, string[] parts)
    {
        for (int i = 2; i + 1 < parts.Length; i += 2)
        {
            var sku = parts[i].Trim();
            if (sku.Length == 0)
                continue;
            if (!int.TryParse(parts[i + 1], out var qty) || qty <= 0)
                continue;

            var price = CalculatePrice(sku, qty);
            order.Lines.Add(new OrderLine { Sku = sku, Quantity = qty, UnitPrice = price });
        }
    }

    private static decimal CalculatePrice(string sku, int qty)
    {
        if (sku.StartsWith("PRM", StringComparison.Ordinal) && qty > 10)
            return 9.99m;
        if (sku.StartsWith("STD", StringComparison.Ordinal))
            return 4.99m;
        return 0m;
    }
}
